import unittest
from candidate import unique

class TestUnique(unittest.TestCase):
    def test_unique_list(self):
        self.assertEqual(unique([5, 3, 5, 2, 3, 3, 9, 0, 123]), [0, 2, 3, 5, 9, 123])

    def test_unique_empty_list(self):
        self.assertEqual(unique([]), [])

    def test_unique_single_element_list(self):
        self.assertEqual(unique([5]), [5])

    def test_unique_list_with_duplicates(self):
        self.assertEqual(unique([5, 5, 5, 5]), [5])

    def test_unique_list_with_negative_numbers(self):
        self.assertEqual(unique([-5, 3, -5, 2, 3, 3, 9, 0, 123]), [-5, 0, 2, 3, 9, 123])

    def test_unique_list_with_floats(self):
        self.assertEqual(unique([5.5, 3.3, 5.5, 2.2, 3.3, 3.3, 9.9, 0.0, 123.123]), [0.0, 2.2, 3.3, 5.5, 9.9, 123.123])

    def test_unique_list_with_mixed_types(self):
        with self.assertRaises(TypeError):
            unique([5, 'a', 5, 2, 'b', 3, 3, 9, 0, 123])

    def test_unique_none_input(self):
        with self.assertRaises(TypeError):
            unique(None)

    def test_unique_non_list_input(self):
        with self.assertRaises(TypeError):
            unique(123)

if __name__ == '__main__':
    unittest.main()
